import{_ as t,o as d,c as a,a0 as o}from"./chunks/framework.veCcaNqE.js";const p=JSON.parse('{"title":"复杂示例 2：上下文模型索引","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/examples/framework-example2/domain-models.md","filePath":"zh-cn/examples/framework-example2/domain-models.md"}'),r={name:"zh-cn/examples/framework-example2/domain-models.md"};function i(n,e,s,c,m,l){return d(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="复杂示例-2-上下文模型索引" tabindex="-1">复杂示例 2：上下文模型索引 <a class="header-anchor" href="#复杂示例-2-上下文模型索引" aria-label="Permalink to &quot;复杂示例 2：上下文模型索引&quot;">​</a></h1><p><a href="/ospf/examples/framework-example2/domain-models.html">English</a></p><p>本索引是 <code>framework_demo/demo2</code> 下 11 个有界上下文的文档边界。每个链接页都按领域模型模板的顺序描述一个上下文契约；索引只承担导航和模式说明，变量、中间值、断言、约束及目标函数的细节以各上下文页面为准。</p><h2 id="_1-上下文图与导航" tabindex="-1">1. 上下文图与导航 <a class="header-anchor" href="#_1-上下文图与导航" aria-label="Permalink to &quot;1. 上下文图与导航&quot;">​</a></h2><p>上下文依赖方向为：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes material-theme-darker material-theme-lighter vp-code" tabindex="0"><code><span class="line"><span>aircraft → stowage → {mac, airworthiness_security, soft_security,</span></span>
<span class="line"><span>                      mac_optimization, express_effectiveness,</span></span>
<span class="line"><span>                      loading_effectiveness, redundancy,</span></span>
<span class="line"><span>                      recommended_weight_equalization, payload_maximization}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><code>aircraft</code> 提供飞机、甲板、燃油、舱位和邻接数据；<code>stowage</code> 消费这些配置并负责货物到舱位的分配及装载表达式。其余上下文消费共享的装载值，分别负责平衡、安全、效能或载荷职责。</p><h2 id="_2-上下文模型页面" tabindex="-1">2. 上下文模型页面 <a class="header-anchor" href="#_2-上下文模型页面" aria-label="Permalink to &quot;2. 上下文模型页面&quot;">​</a></h2><table tabindex="0"><thead><tr><th>上下文</th><th>职责</th><th>本地模型</th></tr></thead><tbody><tr><td><code>aircraft</code></td><td>飞机、甲板、舱位、燃油、ULD 和邻接数据</td><td><a href="./domain-aircraft/domain-model.html">飞机</a></td></tr><tr><td><code>stowage</code></td><td>货物-舱位分配、调整、装载数量、重量及核心装载限制</td><td><a href="./domain-stowage/domain-model.html">装载分配</a></td></tr><tr><td><code>mac</code></td><td>扭矩、CLIM、指数和 MAC 中间值</td><td><a href="./domain-mac/domain-model.html">平均气动弦（MAC）</a></td></tr><tr><td><code>airworthiness_security</code></td><td>密度、累积/区域载荷、载荷、总重量、包络线、配平和 CLIM 限制</td><td><a href="./domain-airworthiness_security/domain-model.html">适航安全</a></td></tr><tr><td><code>soft_security</code></td><td>空舱位、舱门、空载分离和压舱物等软偏好</td><td><a href="./domain-soft_security/domain-model.html">软安全</a></td></tr><tr><td><code>mac_optimization</code></td><td>纵向/横向平衡及水平安定面限制与目标</td><td><a href="./domain-mac_optimization/domain-model.html">MAC 优化</a></td></tr><tr><td><code>express_effectiveness</code></td><td>必须发运和货物优先级顺序</td><td><a href="./domain-express_effectiveness/domain-model.html">快件效能</a></td></tr><tr><td><code>loading_effectiveness</code></td><td>同源/同目的地邻接、装载顺序、复称、拖车和序列策略</td><td><a href="./domain-loading_effectiveness/domain-model.html">装载效能</a></td></tr><tr><td><code>redundancy</code></td><td>冗余和实验纵向平衡限制</td><td><a href="./domain-redundancy/domain-model.html">冗余</a></td></tr><tr><td><code>recommended_weight_equalization</code></td><td>货物顺序、优先级预约及建议载重量偏差</td><td><a href="./domain-recommended_weight_equalization/domain-model.html">建议载重量均衡</a></td></tr><tr><td><code>payload_maximization</code></td><td>最大载荷限制和载荷目标</td><td><a href="./domain-payload_maximization/domain-model.html">载荷最大化</a></td></tr></tbody></table><p>每个页面都提供中文或英文镜像链接；父页面负责说明各模式的精确注册边界。</p><h2 id="_3-模式注册说明" tabindex="-1">3. 模式注册说明 <a class="header-anchor" href="#_3-模式注册说明" aria-label="Permalink to &quot;3. 模式注册说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>普通模型中的上下文</th><th>边界</th></tr></thead><tbody><tr><td><code>LoadingOrder</code></td><td><code>aircraft</code></td><td>仅导出配置，不注册元模型或求解</td></tr><tr><td><code>FullLoad</code></td><td><code>stowage</code>、<code>mac</code>、<code>airworthiness_security</code>、<code>soft_security</code>、<code>mac_optimization</code>、<code>express_effectiveness</code>、<code>loading_effectiveness</code></td><td>适航上下文可能移到 Benders 子问题</td></tr><tr><td><code>Predistribution</code></td><td>FullLoad 上下文加 <code>redundancy</code></td><td>装载顺序管线受模式控制</td></tr><tr><td><code>WeightRecommendation</code></td><td><code>stowage</code>、<code>mac</code>、<code>airworthiness_security</code>、<code>express_effectiveness</code>、<code>recommended_weight_equalization</code>、<code>payload_maximization</code></td><td>推荐偏差和载荷目标是模式专属</td></tr></tbody></table><p>上下文中存在类或模型文件，并不等同于约束已经生效；只有所选模式的管线生成器返回的管线才会进入该模式的模型。</p>`,13)])])}const _=t(r,[["render",i]]);export{p as __pageData,_ as default};
